package com.example.uniroom;
import android.os.*;import android.content.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.uniroom.model.Models.*;import com.example.uniroom.network.*;import retrofit2.*;
public class DashboardActivity extends AppCompatActivity{Session s;protected void onCreate(Bundle b){super.onCreate(b);s=new Session(this);if(s.id()<0){startActivity(new Intent(this,LoginActivity.class));finish();return;}setContentView(R.layout.activity_dashboard);((TextView)findViewById(R.id.welcome)).setText("Welcome, "+s.name()+"!");findViewById(R.id.schedule).setOnClickListener(v->startActivity(new Intent(this,ScheduleActivity.class)));findViewById(R.id.rooms).setOnClickListener(v->startActivity(new Intent(this,FindRoomActivity.class)));findViewById(R.id.profile).setOnClickListener(v->startActivity(new Intent(this,ProfileActivity.class)));load();}void load(){Client.api().schedule(s.id()).enqueue(new Callback<ListResponse<Schedule>>(){public void onResponse(Call<ListResponse<Schedule>> c,Response<ListResponse<Schedule>> r){if(r.body()!=null&&r.body().data!=null&&!r.body().data.isEmpty()){Schedule x=r.body().data.get(0);((TextView)findViewById(R.id.nextText)).setText(x.subject_code+" • "+x.room_name+" • "+x.day_of_week+" "+x.start_time);}else ((TextView)findViewById(R.id.nextText)).setText("No schedule available");}public void onFailure(Call<ListResponse<Schedule>> c,Throwable t){((TextView)findViewById(R.id.nextText)).setText("Schedule unavailable");}});}}
